pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != c.owner());
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(address(c), amount);
        vm.prank(caller);
        bool ok = true;
        try c.withdraw(amount) {
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
